const listSchedulesWithStatus = `-- name: ListSchedulesWithStatus :many
SELECT
    s.id, s.organization_id, s.name, s.run_time, s.days_of_week, s.note, s.is_active, s.next_run_at, s.last_run_at, s.last_run_occurrence_at, s.created_at, s.updated_at,
    run.id AS last_run_id,
    run.status AS last_run_status,
    run.created_at AS last_run_created_at
FROM procurement.schedules s
LEFT JOIN LATERAL (
    SELECT id, status, created_at
    FROM procurement.inquiry_runs
    WHERE organization_id = s.organization_id AND schedule_ref = s.id
    ORDER BY id DESC
    LIMIT 1
) run ON TRUE
WHERE s.organization_id = $1
ORDER BY s.id ASC
`

